/*
 * The face-colour encoding in toRs2Hsb is adapted from Rainbow Rave by geheur
 * (https://github.com/geheur/rainbow-rave), BSD 2-Clause; see LICENSE.
 */
package com.swingrainbow;

import java.awt.Color;

/** Colour maths for cycling swing trails: a hue wheel position over time, and the game's HSB packing. */
final class SwingColors
{
	/** Client cycles (20ms each) in one lap of the colour wheel for a given speed. */
	static int periodCycles(int colorSpeedMs)
	{
		return Math.max(1, colorSpeedMs / 20);
	}

	/**
	 * @param hash per-trail value so neighbouring trails differ
	 * @return a fully saturated colour for this point in the cycle
	 */
	static Color rainbow(int hash, int gameCycle, int colorSpeedMs)
	{
		int period = periodCycles(colorSpeedMs);
		float hue = Math.floorMod(hash + gameCycle, period) / (float) period;
		return Color.getHSBColor(hue, 1.0f, 1.0f);
	}

	/** Packs a colour into the 16-bit hue/saturation/brightness form model face colours use. */
	static int toRs2Hsb(Color color)
	{
		float[] hsb = Color.RGBtoHSB(color.getRed(), color.getGreen(), color.getBlue(), null);

		// Avoid going white at full saturation, or dark at low saturation.
		hsb[2] -= Math.min(hsb[1], hsb[2] / 2);

		int hue = (int) (hsb[0] * 63);
		int saturation = (int) (hsb[1] * 7);
		int brightness = (int) (hsb[2] * 127);
		return (hue << 10) + (saturation << 7) + brightness;
	}

	private SwingColors()
	{
	}
}

package com.swingrainbow;

import java.util.HashSet;
import java.util.Set;

/** Which graphics-object ids count as a weapon swing trail. */
final class SwingGraphics
{
	/**
	 * Dragon halberd special trails (SpotanimID.DRAGON_HALBERD_SPECIAL_*). Scythe swings reuse these,
	 * which is how Rainbow Rave recolours both: red 478/506/1172/1231, white 1232-1235,
	 * dark red 1891-1894, blue 1895-1898.
	 */
	static final int[] KNOWN = {
		478, 506, 1172,
		1231, 1232, 1233, 1234, 1235,
		1891, 1892, 1893, 1894, 1895, 1896, 1897, 1898,
	};

	/** Parses "1234, 5678" style input; blanks and non-numbers are skipped. */
	static Set<Integer> parseIds(String csv)
	{
		Set<Integer> ids = new HashSet<>();
		if (csv == null)
		{
			return ids;
		}
		for (String part : csv.split(","))
		{
			try
			{
				ids.add(Integer.parseInt(part.trim()));
			}
			catch (NumberFormatException ignored)
			{
				// skip blanks and typos
			}
		}
		return ids;
	}

	static Set<Integer> build(boolean includeKnown, String extraCsv)
	{
		Set<Integer> ids = parseIds(extraCsv);
		if (includeKnown)
		{
			for (int id : KNOWN)
			{
				ids.add(id);
			}
		}
		return ids;
	}

	private SwingGraphics()
	{
	}
}

package com.swingrainbow;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(SwingRainbowConfig.GROUP)
public interface SwingRainbowConfig extends Config
{
	String GROUP = "swingrainbow";

	@ConfigItem(
		position = 0,
		keyName = "recolorKnownSwings",
		name = "Halberd & scythe swings",
		description = "Recolor the dragon halberd and scythe swing trails."
	)
	default boolean recolorKnownSwings()
	{
		return true;
	}

	@ConfigItem(
		position = 1,
		keyName = "extraGraphicIds",
		name = "Extra graphic IDs",
		description = "More swing graphics to recolor, comma separated (for example the crystal halberd). Use \"Show graphic IDs\" to find them."
	)
	default String extraGraphicIds()
	{
		return "";
	}

	@ConfigItem(
		position = 2,
		keyName = "rainbow",
		name = "Rainbow",
		description = "Cycle through the rainbow. Turn off to use the custom color instead."
	)
	default boolean rainbow()
	{
		return true;
	}

	@Range(min = 500, max = 20000)
	@ConfigItem(
		position = 3,
		keyName = "colorSpeed",
		name = "Color speed (ms)",
		description = "Milliseconds for the colors to make one full lap of the rainbow. Only used when Rainbow is on."
	)
	default int colorSpeed()
	{
		return 3000;
	}

	@ConfigItem(
		position = 4,
		keyName = "customColor",
		name = "Custom color",
		description = "The color used for every swing when Rainbow is off. The game only stores a limited palette, so the shade is approximate."
	)
	default Color customColor()
	{
		return Color.MAGENTA;
	}

	@ConfigItem(
		position = 5,
		keyName = "logGraphicIds",
		name = "Show graphic IDs",
		description = "Print the id of every graphic that appears next to you in chat. Turn on, swing your weapon, read the id, put it in Extra graphic IDs, then turn this off."
	)
	default boolean logGraphicIds()
	{
		return false;
	}
}

package com.swingrainbow;

import com.google.inject.Provides;
import java.util.Collections;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GraphicsObject;
import net.runelite.api.Model;
import net.runelite.api.Player;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GraphicsObjectCreated;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@PluginDescriptor(
	name = "Swing Rainbow",
	description = "Cycles halberd and scythe swing trails through the rainbow.",
	tags = {"scythe", "halberd", "swing", "rainbow", "color"}
)
public class SwingRainbowPlugin extends Plugin
{
	/** Graphics within this many local units (128 per tile) of you are reported by "Show graphic IDs". */
	private static final int LOG_RADIUS = 3 * 128;

	@Inject
	private Client client;

	@Inject
	private SwingRainbowConfig config;

	@Inject
	private ChatMessageManager chatMessageManager;

	private volatile Set<Integer> swingIds = Collections.emptySet();

	@Provides
	SwingRainbowConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SwingRainbowConfig.class);
	}

	@Override
	protected void startUp()
	{
		rebuildIds();
	}

	@Override
	protected void shutDown()
	{
		swingIds = Collections.emptySet();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (SwingRainbowConfig.GROUP.equals(event.getGroup()))
		{
			rebuildIds();
		}
	}

	private void rebuildIds()
	{
		swingIds = SwingGraphics.build(config.recolorKnownSwings(), config.extraGraphicIds());
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		Set<Integer> ids = swingIds;
		if (ids.isEmpty())
		{
			return;
		}

		int cycle = client.getGameCycle();
		boolean rainbow = config.rainbow();
		int speed = config.colorSpeed();
		int custom = SwingColors.toRs2Hsb(config.customColor());
		for (GraphicsObject graphic : client.getTopLevelWorldView().getGraphicsObjects())
		{
			if (!ids.contains(graphic.getId()))
			{
				continue;
			}

			int packed = rainbow
				? SwingColors.toRs2Hsb(SwingColors.rainbow(graphic.getLocation().hashCode(), cycle, speed))
				: custom;
			recolorAllFaces(graphic.getModel(), packed);
		}
	}

	@Subscribe
	public void onGraphicsObjectCreated(GraphicsObjectCreated event)
	{
		if (!config.logGraphicIds() || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		Player local = client.getLocalPlayer();
		LocalPoint where = event.getGraphicsObject().getLocation();
		if (local == null || local.getLocalLocation().distanceTo(where) > LOG_RADIUS)
		{
			return;
		}

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage("Swing Rainbow: graphic id " + event.getGraphicsObject().getId())
			.build());
	}

	private static void recolorAllFaces(Model model, int rs2hsb)
	{
		if (model == null)
		{
			return;
		}

		fill(model.getFaceColors1(), rs2hsb);
		fill(model.getFaceColors2(), rs2hsb);
		fill(model.getFaceColors3(), rs2hsb);
	}

	private static void fill(int[] faceColors, int value)
	{
		for (int i = 0; i < faceColors.length; i++)
		{
			faceColors[i] = value;
		}
	}
}

package com.swingrainbow;

import java.awt.Color;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

public class SwingRainbowTest
{
	@Test
	public void parseIdsSkipsBlanksAndJunk()
	{
		Set<Integer> ids = SwingGraphics.parseIds(" 1700, ,abc,1701,");

		assertEquals(2, ids.size());
		assertTrue(ids.contains(1700));
		assertTrue(ids.contains(1701));
		assertEquals(0, SwingGraphics.parseIds(null).size());
	}

	@Test
	public void buildCombinesKnownAndExtraAndCanDropKnown()
	{
		Set<Integer> both = SwingGraphics.build(true, "9999");
		assertTrue(both.contains(9999));
		assertTrue(both.contains(1231));
		assertTrue(both.contains(1898));
		assertEquals(SwingGraphics.KNOWN.length + 1, both.size());

		Set<Integer> extraOnly = SwingGraphics.build(false, "9999");
		assertEquals(1, extraOnly.size());
		assertFalse(extraOnly.contains(1231));
	}

	@Test
	public void rainbowColorsDifferByHash()
	{
		assertNotEquals(
			SwingColors.rainbow(0, 100, 3000),
			SwingColors.rainbow(37, 100, 3000));
	}

	@Test
	public void negativeHashStillWrapsIntoTheWheel()
	{
		Color c = SwingColors.rainbow(-123456789, 7, 3000);
		assertEquals(255, Math.max(c.getRed(), Math.max(c.getGreen(), c.getBlue())));
	}

	@Test
	public void colorCompletesALapAfterOnePeriod()
	{
		int period = SwingColors.periodCycles(3000);
		assertEquals(150, period);
		assertEquals(
			SwingColors.rainbow(0, 10, 3000),
			SwingColors.rainbow(0, 10 + period, 3000));
	}

	@Test
	public void packedHsbFitsSixteenBitsAndTracksHue()
	{
		int red = SwingColors.toRs2Hsb(Color.RED);
		int blue = SwingColors.toRs2Hsb(Color.BLUE);

		assertTrue(red >= 0 && red < 1 << 16);
		assertTrue(blue >= 0 && blue < 1 << 16);
		assertNotEquals(red, blue);
	}
}
